begin;
create function pg_temp.assert_ok(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',message; end if; end $$;
create temporary table test_context(owner_id uuid default gen_random_uuid(),member_id uuid default gen_random_uuid(),outsider_id uuid default gen_random_uuid(),gid uuid,pid uuid,eid uuid,code text,deadline timestamptz);
insert into test_context default values;
grant all on test_context to authenticated;
insert into auth.users(id,email,raw_user_meta_data) select owner_id,'owner-'||owner_id||'@example.invalid','{"display_name":"Organizer"}'::jsonb from test_context union all select member_id,'member-'||member_id||'@example.invalid','{"display_name":"Member"}'::jsonb from test_context union all select outsider_id,'outsider-'||outsider_id||'@example.invalid','{}'::jsonb from test_context;
select set_config('request.jwt.claim.sub',owner_id::text,true),set_config('request.jwt.claim.role','authenticated',true) from test_context;
set local role authenticated;
update test_context set gid=public.create_group('Verification group');
update test_context t set code=g.join_code from public.groups g where g.id=t.gid;
update test_context t set pid=p.id,deadline=p.deadline_at from public.issue_periods p where p.group_id=t.gid;
select pg_temp.assert_ok((select count(*)=1 from public.groups),'organizer sees group');
select pg_temp.assert_ok((select role='organizer' and not email_enabled from public.memberships),'organizer role and opt-in default');
insert into public.reflections(group_id,period_id,user_id,body,status) select gid,pid,owner_id,'A small weekly accomplishment.','submitted' from test_context;
-- 0003 allows many reflections per person per week; see verify_notes.sql.
select set_config('request.jwt.claim.sub',member_id::text,true) from test_context;
select pg_temp.assert_ok((select count(*)=0 from public.groups),'nonmember cannot read group');
select public.join_group(code) from test_context;
select public.join_group(code) from test_context;
select pg_temp.assert_ok((select count(*)=2 from public.memberships),'join is idempotent');
select public.set_email_preference(gid,true) from test_context;
select pg_temp.assert_ok((select email_enabled from public.memberships where user_id=auth.uid()),'email opt-in persists');
insert into public.reflections(group_id,period_id,user_id,body,status) select gid,pid,member_id,'Looking forward to a family visit.','submitted' from test_context;
do $$ begin begin perform public.close_issue(gid,pid) from test_context; raise exception 'FAILED member published'; exception when raise_exception then if SQLERRM<>'Organizer required' then raise; end if; end; end $$;
select set_config('request.jwt.claim.sub',outsider_id::text,true) from test_context;
select pg_temp.assert_ok((select count(*)=0 from public.reflections),'outsider cannot read reflections');
select pg_temp.assert_ok((select count(*)=0 from public.memberships),'outsider cannot read memberships');
select pg_temp.assert_ok((select count(*)=0 from public.issue_periods),'outsider cannot read periods');
do $$ begin begin insert into public.reflections(group_id,period_id,user_id,body,status) select gid,pid,outsider_id,'Intrusion','submitted' from test_context; raise exception 'FAILED outsider write accepted'; exception when insufficient_privilege then null; end; end $$;
select set_config('request.jwt.claim.sub',owner_id::text,true) from test_context;
update test_context set eid=public.close_issue(gid,pid);
select pg_temp.assert_ok((select count(*)=1 from public.editions),'one edition created');
select pg_temp.assert_ok((select count(*)=2 from public.edition_sources),'both contributions snapshotted');
select pg_temp.assert_ok((select count(*)=1 from public.issue_periods where closed_at is null),'next period opened');
select pg_temp.assert_ok((select p.deadline_at=t.deadline from public.issue_periods p join test_context t on p.group_id=t.gid where p.closed_at is null),'manual closure retains deadline');
select pg_temp.assert_ok((select public.close_issue(gid,pid)=eid from test_context),'repeated closure returns same edition');
select pg_temp.assert_ok((select count(*)=1 from public.editions),'repeated closure does not duplicate edition');
do $$ begin begin update public.reflections set body='Changed after cutoff' where user_id=auth.uid(); raise exception 'FAILED closed reflection changed'; exception when raise_exception then if SQLERRM<>'Period is closed' then raise; end if; end; end $$;
select set_config('request.jwt.claim.sub',outsider_id::text,true) from test_context;
select pg_temp.assert_ok((select count(*)=0 from public.editions),'outsider cannot read editions');
select pg_temp.assert_ok((select count(*)=0 from public.edition_sources),'outsider cannot read source snapshots');
reset role;
select pg_temp.assert_ok((select count(*)=8 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity),'all eight tables have RLS');
select pg_temp.assert_ok((select not public and file_size_limit=10485760 from storage.buckets where id='reflection-audio'),'audio bucket private and limited to 10 MB');
select pg_temp.assert_ok((public.next_weekly_deadline('America/Vancouver','2026-11-07 20:00Z') at time zone 'America/Vancouver')='2026-11-08 18:00'::timestamp,'Sunday 6pm Vancouver deadline');
rollback;
select 'PASS: membership isolation, roles, opt-in, snapshots, idempotent closure, edit lock, RLS, private storage and timezone. Test data rolled back.' as verification;